def glob_match(pattern, name):
    """
    Match a string against a glob pattern with fnmatch.fnmatchcase semantics.
    Supports:
      * - matches any sequence of characters (including empty)
      ? - matches any single character
      [seq] - matches any single character in seq
      [!seq] - matches any single character not in seq
      A ] immediately after [ or [! is treated as a literal character
      An unterminated [ is treated as a literal [
    Matching is anchored (entire string must match).
    """

    def _match(pattern, name, p_idx, n_idx):
        """
        Recursive matcher with memoization-like approach.
        p_idx: current index in pattern
        n_idx: current index in name
        Returns True if pattern[p_idx:] matches name[n_idx:]
        """
        # Base case: both exhausted
        if p_idx >= len(pattern) and n_idx >= len(name):
            return True
        # Pattern exhausted but name not -> no match
        if p_idx >= len(pattern):
            return False
        # Name exhausted but pattern not -> check if remaining pattern can match empty
        if n_idx >= len(name):
            # Only possible if remaining pattern consists entirely of *'s
            rest = pattern[p_idx:]
            for ch in rest:
                if ch != '*':
                    return False
            return True

        p_char = pattern[p_idx]

        if p_char == '*':
            # * matches any sequence. Try matching 0, 1, 2, ... characters
            # Optimization: skip consecutive *'s
            while p_idx < len(pattern) and pattern[p_idx] == '*':
                p_idx += 1
            # Now try to match pattern[p_idx:] against name[k:] for k from n_idx to len(name)
            for k in range(n_idx, len(name) + 1):
                if _match(pattern, name, p_idx, k):
                    return True
            return False

        elif p_char == '?':
            # Matches exactly one character
            if _match(pattern, name, p_idx + 1, n_idx + 1):
                return True
            return False

        elif p_char == '[':
            # Parse the character class
            end = _parse_bracket(pattern, p_idx)
            if end is None:
                # Unterminated [, treat as literal [
                if _match(pattern, name, p_idx + 1, n_idx + 1):
                    return True
                return False
            else:
                # pattern[p_idx:end+1] is the bracket expression
                # Check if name[n_idx] is in the class
                if _char_in_class(name[n_idx], pattern[p_idx:end+1]):
                    if _match(pattern, name, end + 1, n_idx + 1):
                        return True
                return False

        else:
            # Literal character
            if p_char == name[n_idx]:
                if _match(pattern, name, p_idx + 1, n_idx + 1):
                    return True
            return False

    def _parse_bracket(pattern, start):
        """
        Given pattern[start] == '[', find the matching ']'.
        Returns the index of the closing ']' or None if unterminated.
        A ']' immediately after '[' or '[!' is treated as a literal.
        """
        i = start + 1  # index after '['
        # Check for negation
        negated = False
        if i < len(pattern) and pattern[i] == '!':
            negated = True
            i += 1
        # Now find the closing ']'
        # A ']' at position i (right after '[' or '[!') is a literal
        if i >= len(pattern):
            return None
        if pattern[i] == ']':
            # This ] is a literal, continue looking
            i += 1
            while i < len(pattern):
                if pattern[i] == ']':
                    return i
                i += 1
            return None
        else:
            while i < len(pattern):
                if pattern[i] == ']':
                    return i
                i += 1
            return None

    def _char_in_class(char, bracket_expr):
        """
        Check if char is in the bracket expression bracket_expr.
        bracket_expr includes the surrounding [ and ].
        """
        # bracket_expr is like "[!abc]" or "[a-z]" etc.
        inner = bracket_expr[1:-1]  # strip [ and ]
        negated = False
        if inner.startswith('!'):
            negated = True
            inner = inner[1:]

        # Handle literal ] that was right after [ or [!
        # In our parsing, if ] was literal, it would be in inner
        # We need to check if char matches any of the ranges/chars in inner

        i = 0
        matched = False
        while i < len(inner):
            if i + 2 < len(inner) and inner[i+1] == '-':
                # Range: inner[i] - inner[i+2]
                lo = inner[i]
                hi = inner[i+2]
                if lo <= char <= hi:
                    matched = True
                    break
                i += 3
            else:
                if inner[i] == char:
                    matched = True
                    break
                i += 1

        if negated:
            return not matched
        else:
            return matched

    return _match(pattern, name, 0, 0)
