def glob_match(pattern, name):
    """
    Match a name against a glob pattern with fnmatch.fnmatchcase semantics.
    Supports *, ?, [abc], [a-z], [!abc].
    ] immediately after [ or [! is a literal.
    Unterminated [ is a literal [.
    Match is anchored to the whole string.
    """
    n = len(name)
    p = len(pattern)

    # We'll use memoization with (pi, ni) where pi is pattern index, ni is name index
    from functools import lru_cache

    @lru_cache(maxsize=None)
    def match(pi, ni):
        # If we've reached the end of the pattern
        if pi == p:
            return ni == n

        # If we've reached the end of the name but pattern still has stuff
        if ni == n:
            # Check if remaining pattern can match empty string
            # Only * can match empty
            while pi < p and pattern[pi] == '*':
                pi += 1
            return pi == p

        ch = pattern[pi]

        if ch == '*':
            # * matches any run including empty
            # Try matching 0, 1, 2, ... characters with *
            # First, skip consecutive *s
            while pi < p and pattern[pi] == '*':
                pi += 1
            # Now try to match the rest of the pattern against name starting at various positions
            if pi == p:
                return True  # * at end matches everything remaining
            for k in range(ni, n + 1):
                if match(pi, k):
                    return True
            return False

        elif ch == '?':
            # ? matches exactly one character
            return match(pi + 1, ni + 1)

        elif ch == '[':
            # Parse the character class
            # Check for unterminated [
            # Find the closing ]
            pi2 = pi + 1
            negated = False
            if pi2 < p and pattern[pi2] == '!':
                negated = True
                pi2 += 1

            # If ] is immediately after [ or [!, it's a literal ]
            if pi2 < p and pattern[pi2] == ']':
                # ] is literal, need to find the next ]
                pi2 += 1

            # Find the closing ]
            while pi2 < p and pattern[pi2] != ']':
                pi2 += 1

            if pi2 >= p:
                # Unterminated [ is a literal [
                return name[ni] == '[' and match(pi + 1, ni + 1)

            # Extract the class content
            class_content = pattern[pi + 1:pi2]
            # The next pattern index after the ]
            next_pi = pi2 + 1

            # Check if the current name character matches the class
            c = name[ni]
            matched = False

            if len(class_content) > 0:
                # Parse ranges
                i = 0
                while i < len(class_content):
                    if i + 2 < len(class_content) and class_content[i + 1] == '-':
                        # Range
                        start = class_content[i]
                        end = class_content[i + 2]
                        if start <= c <= end:
                            matched = True
                            break
                        i += 3
                    else:
                        if c == class_content[i]:
                            matched = True
                            break
                        i += 1

            if negated:
                matched = not matched

            return matched and match(next_pi, ni + 1)

        else:
            # Literal character
            return ch == name[ni] and match(pi + 1, ni + 1)

    result = match(0, 0)
    match.cache_clear()
    return result
