def glob_match(pattern, name):
    # Convert pattern to a list of tokens
    # Tokens can be:
    # - ('char', c) for a literal character
    # - ('star',) for *
    # - ('question',) for ?
    # - ('bracket', chars) where chars is a set of characters, or ('negated_bracket', chars) for negated
    # For bracket expressions, we need to handle ranges

    tokens = []
    i = 0
    n = len(pattern)

    while i < n:
        c = pattern[i]
        if c == '*':
            tokens.append(('star',))
            i += 1
        elif c == '?':
            tokens.append(('question',))
            i += 1
        elif c == '[':
            # Find the closing bracket
            j = i + 1
            negated = False
            if j < n and pattern[j] == '!':
                negated = True
                j += 1

            # Check if ] is immediately after [ or [!
            if j < n and pattern[j] == ']':
                # ] is a literal
                tokens.append(('char', ']'))
                i = j + 1
                continue

            # Parse the bracket expression
            chars = set()
            found_close = False
            while j < n:
                if pattern[j] == ']':
                    found_close = True
                    break
                # Check for range
                if j + 2 < n and pattern[j + 1] == '-':
                    start_char = pattern[j]
                    end_char = pattern[j + 2]
                    if start_char <= end_char:
                        for k in range(ord(start_char), ord(end_char) + 1):
                            chars.add(chr(k))
                    j += 3
                else:
                    chars.add(pattern[j])
                    j += 1

            if not found_close:
                # Unterminated [ is a literal [
                tokens.append(('char', '['))
                i += 1
            else:
                if negated:
                    tokens.append(('negated_bracket', chars))
                else:
                    tokens.append(('bracket', chars))
                i = j + 1
        else:
            tokens.append(('char', c))
            i += 1

    # Now match the tokens against name using dynamic programming or recursion
    # We'll use a recursive approach with memoization, or iterative DP

    m = len(name)
    t = len(tokens)

    # dp[i][j] = True if tokens[i:] matches name[j:]
    # Use bottom-up DP
    dp = [[False] * (m + 1) for _ in range(t + 1)]
    dp[t][m] = True

    # Fill from bottom to top
    for i in range(t - 1, -1, -1):
        token = tokens[i]
        for j in range(m, -1, -1):
            if token[0] == 'star':
                # * matches zero or more characters
                # dp[i][j] = dp[i+1][j] (zero chars) OR (j < m AND dp[i][j+1]) (one or more chars)
                dp[i][j] = dp[i + 1][j] or (j < m and dp[i][j + 1])
            elif token[0] == 'question':
                # ? matches exactly one character
                if j < m:
                    dp[i][j] = dp[i + 1][j + 1]
                else:
                    dp[i][j] = False
            elif token[0] == 'char':
                c = token[1]
                if j < m and name[j] == c:
                    dp[i][j] = dp[i + 1][j + 1]
                else:
                    dp[i][j] = False
            elif token[0] == 'bracket':
                chars = token[1]
                if j < m and name[j] in chars:
                    dp[i][j] = dp[i + 1][j + 1]
                else:
                    dp[i][j] = False
            elif token[0] == 'negated_bracket':
                chars = token[1]
                if j < m and name[j] not in chars:
                    dp[i][j] = dp[i + 1][j + 1]
                else:
                    dp[i][j] = False

    return dp[0][0]
